import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第二十三卦 剝 山地剝 艮上坤下","description":"周易 - 第二十三卦 剝 山地剝 艮上坤下","frontmatter":{"title":"第二十三卦 剝 山地剝 艮上坤下","description":"周易 - 第二十三卦 剝 山地剝 艮上坤下"},"headers":[],"relativePath":"classics/zhouyi/024.md","filePath":"classics/zhouyi/024.md"}'),l={name:"classics/zhouyi/024.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="剝" tabindex="-1">剝 <a class="header-anchor" href="#剝" aria-label="Permalink to “剝”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>不利有攸往。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>剝，剝也，柔變剛也。不利有攸往，小人長也。順而止之，觀象也。君子尚消息盈虛，天行也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>山附地上，剝；上以厚下，安宅。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>剝(爿木)以足，蔑貞兇。象曰：剝(爿木)以足，以滅下也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>剝(爿木)以辨，蔑貞兇。象曰：剝(爿木)以辨，未有與也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>剝之，無咎。象曰：剝之無咎，失上下也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>剝(爿木)以膚，兇。象曰：剝(爿木)以膚，切近災也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>貫魚，以宮人寵，無不利。象曰：以宮人寵，終無尤也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>碩果不食，君子得輿，小人剝廬。象曰：君子得輿，民所載也。小人剝廬，終不可用也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
